function openLeave(){ const c=input('',20,{required:true,placeholder:'지우기'}),msg=warnBox(); const form=el('form',{onsubmit:e=>{e.preventDefault();if(c.value.trim()!=='지우기'){msg.textContent="'지우기'라고 적어 주세요.";return;}busyForm(form,msg,async()=>{await rpc('delete_my_account',{});try{await cloud.sb.auth.signOut({scope:'local'});}catch(x){}await session();say('계정',['계정을 지웠어요. 그동안 고마웠어요.']);openAccount();});}},field("정말 지우려면 '지우기'라고 적어 주세요",c),el('button',{cls:'btn',textContent:'계정 지우기'}),msg); show('계정 지우기',el('div',{cls:'warn',textContent:'되돌릴 수 없어요. 내 정보, 방, 추천곡, 내가 연 잼이 모두 지워지고, 함께한 잼 기록에는 이름만 지워진 채 남아요.'}),form,acts(btn('그만두기',openAccount))); }
const inviteRow=({j,s,x})=>el('div',{cls:'row'},el('div',{cls:'grow'},el('div',{textContent:`${s.title} · ${x.part}`}),sub(`${j.title} · ${nm(j.host)}의 초대`)),btn('수락',()=>answer(x,true)),btn('거절',()=>answer(x,false)));
const answer=(x,yes)=>asMember(()=>rpc('answer_invite',{p_slot:x.id,p_accept:yes}).then(ok=>{if(!ok)throw new Error('초대가 바뀌었어요');}),()=>openAccount());
const infoOf=p=>{const i=cloud.infos.find(x=>x.id===p.id);return i?`${i.real_name} · ${i.part}${i.cohort?` · ${i.cohort}`:''}`:cloud.noInfoTable?'':'정보 없음';};
function memberRows(){ const set=(p,s)=>asMember(()=>rpc('set_member_status',{p_user:p.id,p_status:s}),openAccount), L={pending:'승인 대기',approved:'부원',blocked:'차단'}; const row=p=>el('div',{cls:'row'},el('div',{cls:'grow'},el('div',{textContent:p.nick}),sub([p.role==='leader'?'리더':L[p.status],infoOf(p)].filter(Boolean).join(' · '))),p.id===cloud.uid?null:p.status!=='approved'?btn('승인',()=>set(p,'approved')):null,p.id!==cloud.uid&&p.status==='approved'?btn(p.role==='leader'?'리더 해제':'리더로',()=>asMember(()=>rpc('set_member_role',{p_user:p.id,p_role:p.role==='leader'?'member':'leader'}),openAccount)):null,p.id!==cloud.uid&&p.status!=='blocked'?btn('차단',()=>set(p,'blocked')):null);
  const o={pending:0,approved:1,blocked:2}; return [h2('부원 관리'),...cloud.people.slice().sort((a,b)=>o[a.status]-o[b.status]).map(row)]; }
